const items = $input.all().map(i => i.json);
const fecha = new Date().toLocaleDateString('es-ES', { 
  weekday: 'long', day: 'numeric', month: 'long' 
});

const bloques = items.map((n, i) => 
  `<b>${i + 1}. ${n.titulo}</b>\n` +
  `${n.resumen}\n` +
  `<a href="${n.enlace}">🔗 Leer noticia</a>`
).join('\n\n━━━━━━━━━━\n\n');

const texto = 
  `📰 <b>TUS NOTICIAS</b>\n` +
  `<i>${fecha}</i>\n\n` +
  `━━━━━━━━━━\n\n` +
  `${bloques}\n\n` +
  `━━━━━━━━━━\n` +
  `<i>${items.length} noticias seleccionadas</i>`;

return [{ json: { texto } }];
